{"tool": "sql", "args": {"query": "SELECT (SELECT COUNT(*) FROM devices WHERE JV_default_PCE > 0) AS n_pos, (SELECT AVG(JV_default_PCE) FROM (SELECT JV_default_PCE FROM devices WHERE ETL_stack_sequence LIKE '%SnO2%' AND JV_default_PCE > 0 ORDER BY JV_default_PCE LIMIT 2 OFFSET 2215)) AS median_pce, (SELECT AVG(JV_default_PCE) FROM (SELECT JV_default_PCE FROM devices WHERE ETL_stack_sequence LIKE '%SnO2%' AND JV_default_PCE > 0 ORDER BY JV_default_PCE LIMIT 1 OFFSET 1107)) AS q1, (SELECT AVG(JV_default_PCE) FROM (SELECT JV_default_PCE FROM devices WHERE ETL_stack_sequence LIKE '%SnO2%' AND JV_default_PCE > 0 ORDER BY JV_default_PCE LIMIT 1 OFFSET 3317)) AS q3, (SELECT COUNT(*) FROM devices WHERE ETL_stack_sequence LIKE '%SnO2%' AND JV_default_PCE > 0) AS n_sno2_pos"}}

{"tool": "sql", "args": {"query": "SELECT CASE WHEN JV_default_PCE < 5 THEN '1: <5%' WHEN JV_default_PCE < 10 THEN '2: 5-10%' WHEN JV_default_PCE < 15 THEN '3: 10-15%' WHEN JV_default_PCE < 20 THEN '4: 15-20%' WHEN JV_default_PCE < 25 THEN '5: 20-25%' WHEN JV_default_PCE < 30 THEN '6: 25-30%' ELSE '7: >=30%' END AS pce_bucket, COUNT(*) AS n_devices, COUNT(DISTINCT Ref_DOI_number) AS n_papers, ROUND(AVG(JV_default_PCE),3) AS avg_pce FROM devices WHERE ETL_stack_sequence LIKE '%SnO2%' AND JV_default_PCE IS NOT NULL AND JV_default_PCE > 0 GROUP BY 1 ORDER BY 1"}}

{"tool": "sql", "args": {"query": "SELECT Cell_stack_sequence, COUNT(*) AS n_devices, COUNT(DISTINCT Ref_DOI_number) AS n_papers, ROUND(AVG(CASE WHEN JV_default_PCE>0 THEN JV_default_PCE END),2) AS avg_pce, MAX(JV_default_PCE) AS max_pce FROM devices WHERE ETL_stack_sequence LIKE '%SnO2%' GROUP BY 1 ORDER BY n_devices DESC LIMIT 15"}}

